{
  "pairs": {
    "conflict_4cc337c892b63af539f46e27": {
      "classification": "different_products_origins_or_programs",
      "reason": "Claim 1 states NdFeB magnets (HTS 8505.11.00.70) are excluded from IEEPA Executive Tariffs but subject to Section 301 and Fentanyl tariffs, resulting in ~37% total. Claim 2 confirms this specific exclusion for NdFeB under Annex II while noting SmCo magnets remain fully exposed to both Section 301 and Executive tariffs (~47.1%). The claims address different magnet types (NdFeB vs. SmCo) and their distinct treatment under the IEEPA carve-out, not a contradiction.",
      "verification_question": "Does the Annex II exclusion for HTS 8505.11.00.70 apply to all NdFeB magnets or only specific sub-classifications within that code?"
    },
    "conflict_8d360fb03a35b17a5b366f44": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 describes a tariff rate of 12.5% effective July 24, 2026, for specific PCBs. Claim 2 describes a 125% tariff on the same product type effective April 9, 2025. The audit date is September 10, 2026; thus, these represent sequential policy stages where rates changed over time (from 125% in early 2025 to 12.5% in mid-2026), not a simultaneous conflict.",
      "verification_question": "What specific regulatory action or agreement dated between April 2025 and July 2026 resulted in the reduction from 125% to 12.5%?"
    },
    "conflict_676cf3ce8f58b09d096c5891": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 presents a table showing a total of 12.5% for 2L/4L FR4 PCBs, likely reflecting the post-July 2026 rate or a specific calculation including exemptions. Claim 2 explicitly states a 125% tariff effective April 9, 2025. Given the audit date of September 10, 2026, these represent different points in a timeline of changing rates (April 2025 vs. later dates), not incompatible statements about the same moment.",
      "verification_question": "Does the 12.5% rate in Claim 1 reflect the status after the July 24, 2026 update or a specific exemption scenario distinct from the April 2025 baseline?"
    },
    "conflict_0fd5ddda0b8f459075f9771a": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 states a bare PCB from China is classified under 8534.00.0040 with free base duty but subject to Section 301 unless excluded. Claim 2 provides a specific CBP ruling for a ThermOmegaTech bare PCB (HTS 8534.00.0040) confirming the Free base duty and an additional 25% ad valorem Section 301 duty under Chapter 99 Note 20. The claims are consistent: one establishes the general rule, the other provides a specific application of that rule.",
      "verification_question": "Is there any evidence in the provided text regarding the specific exclusion status (e.g., code 9903.88.69) for the ThermOmegaTech PCB mentioned in Claim 2?"
    },
    "conflict_c90eaebcfbc236fb1cb1b7ac": {
      "classification": "different_dates_or_policy_stages",
      "reason": "Claim 1 states a general rule that China-origin PCBs face a 25% Section 301 tariff unless excluded. Claim 2 states an additional 20% duty effective March 4, 2025, applies to all PCBs regardless of layer count, while noting the 25% exemption for 2/4-layer boards was set to expire end of May (implying a temporary state). The claims describe different tariff layers (Section 301 vs. additional duties) and specific dates (March 2025 vs. general guidance), representing sequential or layered policy stages rather than a direct contradiction.",
      "verification_question": "Did the 'additional 20% duties' effective March 4, 2025, apply cumulatively with the Section 301 tariff for all PCBs, and how did this interact with the temporary 2/4-layer exemption?"
    }
  }
}
